$('#submitObservations').onclick=async()=>{
  const selected=[...document.querySelectorAll('#submissionList input:checked')].map(input=>submissionCandidates[Number(input.dataset.index)]);if(!selected.length||!$('#publishConsent').checked)return;
  const button=$('#submitObservations'),status=$('#submissionStatus');button.disabled=true;button.textContent='Skickar…';status.textContent='Observationerna skickas till serverns automatiska evidensmodell…';clientSubmissionId=clientSubmissionId||crypto.randomUUID();
  try{const response=await fetch('/api/submissions',{method:'POST',headers:{'Content-Type':'application/json','X-OMapMaker-Device':deviceId},body:JSON.stringify({clientSubmissionId,features:selected.map(({cat,obj})=>publicationFeature(cat,obj))})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Observationerna kunde inte skickas');selected.forEach(({obj})=>{obj.syncStatus='submitted';obj.submissionId=result.id;obj.submittedAt=result.createdAt});save();status.textContent=result.candidateCount?`Klart: ${result.featureCount} observationer behandlade · ${result.candidateCount} globala punktobjekt uppdaterade.`:`Klart: ${result.featureCount} observationer sparade som evidens. Automatisk sammanslagning av linjer och områden kommer senare.`;button.textContent='Insända';localStorage.setItem('omapmaker.publishNoticeAccepted','true');await loadGlobalObjects();if(layerPrefs.evidence)await loadEvidence();setTimeout(()=>$('#submissionSheet').close(),1800)}catch(error){status.textContent=error.message;button.disabled=false;button.textContent='Försök igen'}
};
function pointSvg(id){
  const symbol=String(catalog.point.find(entry=>entry[0]===id)?.[1]||id);return normRenderer.pointMarkup(symbol,normContext()).html;
}
function manualObjectSymbol(cat,obj){const stored=String(obj?.symbol||''),geometry={point:'Point',line:'LineString',area:'Polygon'}[cat],definition=symbolDefinition(stored);return definition?.geometry?.includes(geometry)&&normRenderer.definition(stored)?stored:String(item(cat,obj?.objectType||obj?.type)[1]||'')}
function pointIcon(idOrObject){const symbol=typeof idOrObject==='object'?manualObjectSymbol('point',idOrObject):String(catalog.point.find(entry=>entry[0]===idOrObject)?.[1]||idOrObject);return pointIconFromSymbol(symbol,'local-map-object')}
function isomLineStyle(symbol,feature=null){return normRenderer.lineStyles(String(symbol||'506'),feature?.properties||feature||{},normContext()).outer}
function isomCompositeInnerStyle(symbol,feature=null){return normRenderer.lineStyles(String(symbol),feature?.properties||feature||{},normContext()).inner||null}
function lineStyle(id){return isomLineStyle(catalog.line.find(entry=>entry[0]===id)?.[1]||id)}
function areaStyle(id){const symbol=String(catalog.area.find(entry=>entry[0]===id)?.[1]||id);return{...isomAreaStyle(symbol,{boundary:id==='forbidden'?'clear':undefined}),className:`isom-pattern-${symbol}`}}
function latlngs(coords){return coords.map(c=>[c[1],c[0]])}
function setLayerSelected(layer,active){if(layer?.eachLayer)return layer.eachLayer(child=>setLayerSelected(child,active));layer?.getElement?.()?.classList.toggle('feature-selected',active)}
function clearSelection(){if(selected)setLayerSelected(selected.layer,false);handles.forEach(h=>map.removeLayer(h));handles=[];selected=null;$('#editBar').classList.add('hidden')}
function setFeatureLayerLatLngs(layer,coordinates){if(layer.setLatLngs)layer.setLatLngs(latlngs(coordinates));else layer.eachLayer?.(child=>child.setLatLngs?.(latlngs(coordinates)))}
function selectFeature(cat,obj,layer){if(mode!=='manual'||recording||generatedEdit)return;clearSelection();selected={cat,obj,layer};setLayerSelected(layer,true);if(cat!=='point')obj.coordinates.forEach((c,i)=>{const h=L.marker([c[1],c[0]],{pane:'fieldPane',icon:L.divIcon({className:'',html:'<span style="display:block;width:18px;height:18px;border-radius:50%;background:#286fc0;border:3px solid white"></span>',iconSize:[18,18],iconAnchor:[9,9]}),draggable:true}).addTo(map);h.on('drag',e=>{const p=e.target.getLatLng();obj.coordinates[i]=[p.lng,p.lat,...obj.coordinates[i].slice(2)];setFeatureLayerLatLngs(layer,obj.coordinates)});h.on('dragend',()=>{markObjectChanged(obj);save()});handles.push(h)});$('#undoVertex').classList.add('hidden');$('#removeVertex').classList.add('hidden');$('#cancelEdit').classList.add('hidden');$('#finishEdit').classList.remove('hidden');$('#finishEdit').textContent='Klar';$('#deleteFeature').classList.remove('hidden');$('#editBar').classList.remove('hidden')}
function applyFieldPresentation(layer){if(layer.eachLayer)return layer.eachLayer(applyFieldPresentation);const el=layer.getElement?.();if(el){el.classList.toggle('foreground-hidden',!layerPrefs.objects);el.style.opacity=String(layerPrefs.opacity/100)}}
function renderPoint(o){const m=L.marker([o.coordinates[1],o.coordinates[0]],{pane:'fieldPane',icon:pointIcon(o),draggable:mode==='manual'}).addTo(map);m.on('add',()=>applyFieldPresentation(m));m.on('dragend',e=>{const p=e.target.getLatLng();o.coordinates=[p.lng,p.lat];o.source='manual-adjustment';markObjectChanged(o);save()});m.on('click',()=>selectFeature('point',o,m));layers.set(o.id,m);applyFieldPresentation(m)}
function renderLine(o){const symbol=manualObjectSymbol('line',o),outer=L.polyline(latlngs(o.coordinates),{pane:'fieldPane',...isomLineStyle(symbol,o),className:`local-map-object isom-symbol-${symbol}`}),innerStyle=isomCompositeInnerStyle(symbol,o);let layer=outer;if(innerStyle){const inner=L.polyline(latlngs(o.coordinates),{pane:'fieldPane',interactive:false,...innerStyle,className:`local-map-object isom-symbol-${symbol}-inner`}),group=L.layerGroup([outer,inner]).addTo(map);group._omapComposite={outer,inner,symbol};layer=group}else outer.addTo(map);outer.on('add',()=>applyFieldPresentation(layer));outer.on('click',()=>selectFeature('line',o,layer));layers.set(o.id,layer);applyFieldPresentation(layer)}
function renderArea(o){const symbol=manualObjectSymbol('area',o),properties={...o,boundary:o.objectType==='forbidden'?'clear':o.boundary},p=L.polygon(latlngs(o.coordinates),{pane:'fieldPane',...isomAreaStyle(symbol,properties),className:`local-map-object isom-pattern-${symbol}`}).addTo(map);p.on('add',()=>{applyFieldPresentation(p);requestAnimationFrame(installWaterPatterns)});p.on('click',()=>selectFeature('area',o,p));layers.set(o.id,p);applyFieldPresentation(p)}
state.observations.forEach(renderPoint);state.tracks.forEach(renderLine);state.areas.forEach(renderArea);
function refreshSymbolPresentation(){state.observations.forEach(o=>layers.get(o.id)?.setIcon(pointIcon(o)));state.tracks.forEach(o=>{const layer=layers.get(o.id),symbol=manualObjectSymbol('line',o);if(layer?._omapComposite){layer._omapComposite.outer.setStyle(isomLineStyle(symbol,o));layer._omapComposite.inner.setStyle(isomCompositeInnerStyle(symbol,o))}else layer?.setStyle?.(isomLineStyle(symbol,o))});state.areas.forEach(o=>{const symbol=manualObjectSymbol('area',o),properties={...o,boundary:o.objectType==='forbidden'?'clear':o.boundary};layers.get(o.id)?.setStyle(isomAreaStyle(symbol,properties))});renderLandCover();renderProjectContours();renderBuildings();renderPavedAreas();renderRoads();renderInfrastructure();renderGlobalObjects()}
map.on('zoomend',()=>{if(workspace?.symbolDisplayMode==='print')refreshSymbolPresentation();else{renderRoads();renderInfrastructure()}renderMagneticNorthLines()});

function labels(){
  const pointButton=$('#pointAction'), pointActive=recording?.cat==='point';
  $('#pointLabel').textContent=name('point',pointActive?recording.type:prefs.point);
  pointButton.classList.toggle('active-tool',pointActive);
  pointButton.querySelector('span').textContent=pointActive?'PLACERA PÅ KARTAN':'PLACERA';
  for(const cat of ['line','area']){
    const button=$(`#${cat}Action`), active=recording?.cat===cat, noun=name(cat,active?recording.type:prefs[cat]);
    button.classList.toggle('recording',active);
    button.querySelector('span').textContent=active?(recording.mode==='gps'?'MÄTER':'RITAR'):(mode==='gps'?'SPELA IN':'RITA');
    button.querySelector('b').textContent=active?`■ ${noun}`:noun;
  }
}
function setMode(next){
  if(recording?.mode==='gps'&&next!=='gps')return toast('Avsluta eller avbryt GPS-inspelningen först');
  if(recording){cancelDrawing(false)}
  clearSelection();mode=next;localStorage.setItem('omapmaker.mode',mode);
  document.body.classList.toggle('manual-mode',mode==='manual');document.body.classList.toggle('gps-mode',mode==='gps');
  $('#gpsMode').classList.toggle('active',mode==='gps');$('#manualMode').classList.toggle('active',mode==='manual');
  $('#modeHint').textContent=mode==='gps'?'GPS · Telefonens position':'MANUELLT · Rita på kartan';
  state.observations.forEach(o=>{const m=layers.get(o.id);mode==='manual'?m.dragging.enable():m.dragging.disable()});labels();
}
$('#gpsMode').onclick=()=>setMode('gps');$('#manualMode').onclick=()=>setMode('manual');

function identity(){const id=crypto.randomUUID();return{id,observationId:id,syncStatus:'local',version:1}}
function addPoint(ll,accuracy,source){if(source==='gps'&&accuracy>50)return toast(`GPS ±${Math.round(accuracy)} m · för osäkert`);const o={...identity(),objectType:prefs.point,symbol:item('point',prefs.point)[1],coordinates:[ll.lng,ll.lat],accuracy,source,quality:'unverified',createdAt:new Date().toISOString()};state.observations.push(o);renderPoint(o);save();toast(`${name('point',prefs.point)} sparad`)}
function showDrawingBar(){clearSelection();$('#undoVertex').classList.remove('hidden');$('#cancelEdit').classList.remove('hidden');$('#finishEdit').classList.remove('hidden');$('#finishEdit').textContent='Slutför';$('#deleteFeature').classList.add('hidden');$('#editBar').classList.remove('hidden')}
function updateTemp(){if(tempLayer)map.removeLayer(tempLayer);if(!currentCoords.length)return;tempLayer=recording.cat==='area'?L.polygon(latlngs(currentCoords),{...areaStyle(recording.type),className:'temp-shape'}).addTo(map):L.polyline(latlngs(currentCoords),{...lineStyle(recording.type),className:'temp-shape'}).addTo(map)}
function beginShape(cat){recording={mode,cat,type:prefs[cat]};currentCoords=[];showDrawingBar();labels();toast(mode==='gps'?`${name(cat,prefs[cat])} spelas in`:`Tryck ut ${cat==='line'?'linjen':'områdets hörn'}`)}
function finishDrawing(){if(!recording)return;const min=recording.cat==='area'?3:2;if(currentCoords.length<min)return toast(`Minst ${min} punkter behövs`);const obj={...identity(),objectType:recording.type,symbol:item(recording.cat,recording.type)[1],coordinates:[...currentCoords],source:recording.mode,quality:'unverified',createdAt:new Date().toISOString()};if(recording.cat==='line'){state.tracks.push(obj);renderLine(obj)}else{state.areas.push(obj);renderArea(obj)}cancelDrawing(false);save();toast('Objekt sparat')}
function cancelDrawing(message=true){if(tempLayer)map.removeLayer(tempLayer);tempLayer=null;recording=null;currentCoords=[];$('#editBar').classList.add('hidden');labels();if(message)toast('Ritningen avbröts')}
function action(cat){
  if(cat==='point'){if(mode==='manual'){recording={mode:'manual',cat:'point',type:prefs.point};labels();toast(`${name('point',prefs.point)} vald · tryck på kartan`)}else if(lastPosition)addPoint(lastPosition.latlng,lastPosition.accuracy,'gps');else toast('GPS söker position · försök igen strax');return}
  if(recording?.cat===cat)return finishDrawing();
  if(recording)return toast('Slutför eller avbryt pågående objekt först');
  if(mode==='gps'&&!lastPosition)return toast('GPS söker position · försök igen strax');
  if(mode==='gps'&&lastPosition.accuracy>50)return toast('GPS-kvaliteten är för låg');
  beginShape(cat);
}
$('#pointAction').onclick=()=>action('point');$('#lineAction').onclick=()=>action('line');$('#areaAction').onclick=()=>action('area');
map.on('click',e=>{if(mode!=='manual')return;if(recording?.cat==='point'){addPoint(e.latlng,0,'manual');recording=null;labels()}else if(recording?.mode==='manual'){currentCoords.push([e.latlng.lng,e.latlng.lat,0,Date.now(),null,null]);updateTemp()}});
$('#undoVertex').onclick=()=>generatedEdit?undoGeneratedGeometryEdit():(currentCoords.pop(),updateTemp());$('#removeVertex').onclick=removeSelectedGeneratedVertex;$('#cancelEdit').onclick=()=>generatedEdit?cancelGeneratedGeometryEdit():cancelDrawing();$('#finishEdit').onclick=()=>generatedEdit?finishGeneratedGeometryEdit():selected?clearSelection():finishDrawing();
$('#deleteFeature').onclick=async()=>{if(!selected)return;const {cat,obj,layer}=selected,submitted=obj.syncStatus==='submitted';if(!confirm(submitted?'Objektet är insänt. Återkalla observationen från servern och radera den lokala kopian?':'Radera detta lokala utkast?'))return;if(submitted){try{const response=await fetch('/api/submissions/withdraw',{method:'POST',headers:{'Content-Type':'application/json','X-OMapMaker-Device':deviceId},body:JSON.stringify({clientObservationIds:[obj.observationId]})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Observationen kunde inte återkallas');if(!result.withdrawn)throw new Error('Servern hittade ingen aktiv observation att återkalla')}catch(error){toast(error.message);return}}map.removeLayer(layer);const list=cat==='point'?state.observations:cat==='line'?state.tracks:state.areas;list.splice(list.indexOf(obj),1);layers.delete(obj.id);clearSelection();save();if(submitted){loadGlobalObjects().catch(()=>{});if(layerPrefs.evidence)loadEvidence().catch(()=>{})}toast(submitted?'Observationen återkallad och raderad':'Lokalt utkast raderat')};

function openSheet(cat){if(recording)return toast('Slutför eller avbryt pågående objekt först');$('#sheetCategory').textContent=cat==='point'?'PLACERA':cat==='line'?'LINJE':'OMRÅDE';$('#sheetTitle').textContent=`Välj ${cat==='point'?'punktobjekt':cat==='line'?'linjeobjekt':'områdestyp'}`;$('#sheetOptions').innerHTML='';catalog[cat].forEach(d=>{const b=document.createElement('button');b.type='button';b.className=d[0]===prefs[cat]?'selected':'';b.innerHTML=`<span class="symbol">${cat==='point'?pointSvg(d[0]):d[1]}</span><span>${d[2]}<small style="display:block;color:#748078">${isomClaim(d[1],manualTypes[d[0]].geometry)}</small></span>`;b.onclick=()=>{prefs[cat]=d[0];save();labels();$('#objectSheet').close();toast(`${d[2]} vald`)};$('#sheetOptions').append(b)});$('#objectSheet').showModal()}
document.querySelectorAll('.tool-menu').forEach(b=>b.onclick=()=>openSheet(b.dataset.category));

function quality(a){return a<=3?['excellent',`★ GPS ± ${Math.round(a)} m · Utmärkt`]:a<=10?['good',`GPS ± ${Math.round(a)} m · Bra`]:a<=50?['warn',`GPS ± ${Math.round(a)} m · Osäkert`]:['bad',`GPS ± ${Math.round(a)} m · Otillräckligt`]}
function refreshGpsButton(){const running=watchId!==null,button=$('#gpsQuality');button.setAttribute('aria-pressed',String(running));button.title=running?'Stäng av GPS':'Starta GPS';if(!running)button.querySelector('span').textContent='GPS av · Starta'}
function oneShotPosition(button,onSuccess){if(!navigator.geolocation)return toast('Positionering stöds inte av webbläsaren');if(button){button.disabled=true;button.classList.add('busy');button.setAttribute('aria-busy','true')}navigator.geolocation.getCurrentPosition(position=>{const latlng=L.latLng(position.coords.latitude,position.coords.longitude);lastPosition={latlng,accuracy:position.coords.accuracy};onSuccess(latlng,position.coords.accuracy);if(button){button.disabled=false;button.classList.remove('busy');button.removeAttribute('aria-busy')}},error=>{if(button){button.disabled=false;button.classList.remove('busy');button.removeAttribute('aria-busy')}toast(error.code===1?'Positionering saknar tillstånd':'Positionen kunde inte hämtas')},{enableHighAccuracy:true,maximumAge:5000,timeout:15000})}
function centerOnCurrentPosition(){const button=$('#centerLocationButton'),show=latlng=>map.setView(latlng,Math.max(map.getZoom(),17),{animate:true});if(lastPosition)return show(lastPosition.latlng);oneShotPosition(button,show)}
function startGps(){if(watchId!==null)return;if(!navigator.geolocation){toast('GPS stöds inte av webbläsaren');return}localStorage.setItem('omapmaker.gpsEnabled','true');$('#gpsQuality').className='';$('#gpsQuality span').textContent='GPS söker position…';watchId=navigator.geolocation.watchPosition(p=>{const ll=L.latLng(p.coords.latitude,p.coords.longitude);lastPosition={latlng:ll,accuracy:p.coords.accuracy};if(!gpsMarker){gpsCircle=L.circle(ll,{pane:'gpsPane',interactive:false,radius:p.coords.accuracy,className:'accuracy'}).addTo(map);gpsMarker=L.circleMarker(ll,{pane:'gpsPane',interactive:false,radius:7,color:'#fff',weight:3,fillColor:'#2677c7',fillOpacity:1,className:'gps-position-marker'}).addTo(map);gpsMarker.bringToFront()}else{gpsMarker.setLatLng(ll);gpsCircle.setLatLng(ll).setRadius(p.coords.accuracy);gpsMarker.bringToFront()}const [cls,label]=quality(p.coords.accuracy);$('#gpsQuality').className=cls;$('#gpsQuality span').textContent=label;if(recording?.mode==='gps'&&p.coords.accuracy<=50){currentCoords.push([p.coords.longitude,p.coords.latitude,p.coords.accuracy,Date.now(),p.coords.altitude,p.coords.altitudeAccuracy]);updateTemp()}},e=>{$('#gpsQuality').className='bad';$('#gpsQuality span').textContent=e.code===1?'GPS saknar tillstånd':'GPS kunde inte hämtas'},{enableHighAccuracy:true,maximumAge:0,timeout:15000});refreshGpsButton()}
function stopGps(){if(recording?.mode==='gps')return toast('Avsluta eller avbryt GPS-inspelningen först');if(watchId!==null)navigator.geolocation.clearWatch(watchId);watchId=null;lastPosition=null;if(gpsMarker)map.removeLayer(gpsMarker);if(gpsCircle)map.removeLayer(gpsCircle);gpsMarker=null;gpsCircle=null;localStorage.setItem('omapmaker.gpsEnabled','false');$('#gpsQuality').className='';refreshGpsButton()}
$('#gpsQuality').onclick=()=>watchId===null?startGps():stopGps();
if(localStorage.getItem('omapmaker.gpsEnabled')!=='false')startGps();else refreshGpsButton();
$('#centerLocationButton').onclick=centerOnCurrentPosition;
if(workspace){$('#centerWorkspaceButton').onclick=fitWorkspace}else $('#centerWorkspaceButton').hidden=true;
function refreshFieldPresentation(){layers.forEach(applyFieldPresentation)}
$('#layersButton').onclick=()=>$('#layersSheet').showModal();
const layersSheet=$('#layersSheet');layersSheet.addEventListener('click',event=>{const bounds=layersSheet.getBoundingClientRect(),outside=event.clientX<bounds.left||event.clientX>bounds.right||event.clientY<bounds.top||event.clientY>bounds.bottom;if(outside)layersSheet.close()});
document.querySelectorAll('input[name=basemap]').forEach(input=>{input.checked=input.value===layerPrefs.basemap;input.onchange=()=>setBase(input.value)});
$('#objectsVisible').checked=layerPrefs.objects;$('#objectsVisible').onchange=e=>{layerPrefs.objects=e.target.checked;saveLayerPrefs();refreshFieldPresentation()};
$('#globalObjectsVisible').checked=layerPrefs.globalObjects;$('#globalObjectsVisible').onchange=e=>{layerPrefs.globalObjects=e.target.checked;saveLayerPrefs();renderGlobalObjects();if(e.target.checked&&!globalObjectData)loadGlobalObjects().catch(error=>toast(error.message))};
