$('#contoursVisible').checked=layerPrefs.contours;if(layerPrefs.contours)contourReference.addTo(map);$('#contoursVisible').onchange=e=>{layerPrefs.contours=e.target.checked;e.target.checked?contourReference.addTo(map):map.removeLayer(contourReference);saveLayerPrefs()};
$('#projectContoursVisible').checked=layerPrefs.projectContours;$('#projectContoursVisible').onchange=e=>{layerPrefs.projectContours=e.target.checked;saveLayerPrefs();renderProjectContours()};
$('#generatedSurfacesVisible').checked=layerPrefs.generatedSurfaces;$('#generatedSurfacesVisible').onchange=e=>{layerPrefs.generatedSurfaces=e.target.checked;saveLayerPrefs();renderLandCover();renderBuildings();renderPavedAreas()};
$('#generatedLinesVisible').checked=layerPrefs.generatedLines;$('#generatedLinesVisible').onchange=e=>{layerPrefs.generatedLines=e.target.checked;saveLayerPrefs();renderLandCover();renderRoads();renderInfrastructure()};
$('#osmLandCoverVisible').checked=layerPrefs.landCover;$('#osmLandCoverVisible').onchange=e=>{layerPrefs.landCover=e.target.checked;saveLayerPrefs();renderLandCover()};
$('#osmBuildingsVisible').checked=layerPrefs.buildings;$('#osmBuildingsVisible').onchange=e=>{layerPrefs.buildings=e.target.checked;saveLayerPrefs();renderBuildings()};
$('#osmPavedAreasVisible').checked=layerPrefs.pavedAreas;$('#osmPavedAreasVisible').onchange=e=>{layerPrefs.pavedAreas=e.target.checked;saveLayerPrefs();renderPavedAreas()};
